module CaveSystem(\n    input clk, rst_n, start,\n    input [15:0] A, H,\n    input [3:0] n, m,\n    input [3:0] from_0, to_0, from_1, to_1, from_2, to_2, from_3, to_3,\n    input [3:0] from_4, to_4, from_5, to_5, from_6, to_6, from_7, to_7,\n    input [3:0] from_8, to_8, from_9, to_9, from_10, to_10, from_11, to_11,\n    input [3:0] from_12, to_12, from_13, to_13, from_14, to_14, from_15, to_15,\n    input [15:0] a_0, h_0, a_1, h_1, a_2, h_2, a_3, h_3,\n    input [15:0] a_4, h_4, a_5, h_5, a_6, h_6, a_7, h_7,\n    input [15:0] a_8, h_8, a_9, h_9, a_10, h_10, a_11, h_11,\n    input [15:0] a_12, h_12, a_13, h_13, a_14, h_14, a_15, h_15,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] PRECOMP     = 3'd1;\n    localparam [2:0] DIJK_INIT   = 3'd2;\n    localparam [2:0] DIJK_SELECT = 3'd3;\n    localparam [2:0] DIJK_RELAX  = 3'd4;\n    localparam [2:0] OUTPUT      = 3'd5;\n    reg [2:0] state, next_state;\n\n    // Edge storage\n    reg [3:0] edge_from [0:15];\n    reg [3:0] edge_to [0:15];\n    reg [31:0] edge_damage [0:15];\n\n    // Dijkstra registers\n    reg [31:0] dist [0:7];\n    reg visited [0:7];\n    reg [3:0] current_node;\n\n    // Counters\n    reg [3:0] edge_cnt;\n    reg [3:0] node_cnt;\n\n    // Temporary damage calculation\n    reg [31:0] k_temp;\n    reg [31:0] damage_temp;\n    integer i;\n\n    // Edge selection functions\n    function [3:0] get_from(input [3:0] idx);\n        case(idx)\n            4'd0:  get_from = from_0;\n            4'd1:  get_from = from_1;\n            4'd2:  get_from = from_2;\n            4'd3:  get_from = from_3;\n            4'd4:  get_from = from_4;\n            4'd5:  get_from = from_5;\n            4'd6:  get_from = from_6;\n            4'd7:  get_from = from_7;\n            4'd8:  get_from = from_8;\n            4'd9:  get_from = from_9;\n            4'd10: get_from = from_10;\n            4'd11: get_from = from_11;\n            4'd12: get_from = from_12;\n            4'd13: get_from = from_13;\n            4'd14: get_from = from_14;\n            4'd15: get_from = from_15;\n            default: get_from = 4'd0;\n        endcase\n    endfunction\n\n    function [3:0] get_to(input [3:0] idx);\n        case(idx)\n            4'd0:  get_to = to_0;\n            4'd1:  get_to = to_1;\n            4'd2:  get_to = to_2;\n            4'd3:  get_to = to_3;\n            4'd4:  get_to = to_4;\n            4'd5:  get_to = to_5;\n            4'd6:  get_to = to_6;\n            4'd7:  get_to = to_7;\n            4'd8:  get_to = to_8;\n            4'd9:  get_to = to_9;\n            4'd10: get_to = to_10;\n            4'd11: get_to = to_11;\n            4'd12: get_to = to_12;\n            4'd13: get_to = to_13;\n            4'd14: get_to = to_14;\n            4'd15: get_to = to_15;\n            default: get_to = 4'd0;\n        endcase\n    endfunction\n\n    function [15:0] get_a(input [3:0] idx);\n        case(idx)\n            4'd0:  get_a = a_0;\n            4'd1:  get_a = a_1;\n            4'd2:  get_a = a_2;\n            4'd3:  get_a = a_3;\n            4'd4:  get_a = a_4;\n            4'd5:  get_a = a_5;\n            4'd6:  get_a = a_6;\n            4'd7:  get_a = a_7;\n            4'd8:  get_a = a_8;\n            4'd9:  get_a = a_9;\n            4'd10: get_a = a_10;\n            4'd11: get_a = a_11;\n            4'd12: get_a = a_12;\n            4'd13: get_a = a_13;\n            4'd14: get_a = a_14;\n            4'd15: get_a = a_15;\n            default: get_a = 16'd0;\n        endcase\n    endfunction\n\n    function [15:0] get_h(input [3:0] idx);\n        case(idx)\n            4'd0:  get_h = h_0;\n            4'd1:  get_h = h_1;\n            4'd2:  get_h = h_2;\n            4'd3:  get_h = h_3;\n            4'd4:  get_h = h_4;\n            4'd5:  get_h = h_5;\n            4'd6:  get_h = h_6;\n            4'd7:  get_h = h_7;\n            4'd8:  get_h = h_8;\n            4'd9:  get_h = h_9;\n            4'd10: get_h = h_10;\n            4'd11: get_h = h_11;\n            4'd12: get_h = h_12;\n            4'd13: get_h = h_13;\n            4'd14: get_h = h_14;\n            4'd15: get_h = h_15;\n            default: get_h = 16'd0;\n        endcase\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            edge_cnt <= 4'd0;\n            node_cnt <= 4'd0;\n            current_node <= 4'd0;\n            for (i = 0; i < 16; i = i + 1) begin\n                edge_from[i] <= 4'd0;\n                edge_to[i] <= 4'd0;\n                edge_damage[i] <= 32'd0;\n            end\n            for (i = 0; i < 8; i = i + 1) begin\n                dist[i] <= 32'hFFFFFFFF;\n                visited[i] <= 1'b0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= PRECOMP;\n                        edge_cnt <= 4'd0;\n                    end\n                end\n\n                PRECOMP: begin\n                    if (edge_cnt < m) begin\n                        edge_from[edge_cnt] <= get_from(edge_cnt);\n                        edge_to[edge_cnt] <= get_to(edge_cnt);\n\n                        // Calculate damage = (ceil(h/A)-1)*a\n                        // Ceil division: (h + A - 1) / A (unsigned)\n                        if (A != 16'd0) begin\n                            k_temp <= ({16'h0, get_h(edge_cnt)} + {16'h0, A} - 32'd1) / {16'h0, A};\n                        end else begin\n                            k_temp <= 32'd0;\n                        end\n                        edge_cnt <= edge_cnt + 4'd1;\n                        state <= PRECOMP;\n                    end else begin\n                        state <= DIJK_INIT;\n                        edge_cnt <= 4'd0;\n                    end\n\n                    // Post-calculation storage (1 cycle delay)\n                    if (edge_cnt != 4'd0) begin\n                        damage_temp <= (k_temp - 32'd1) * {16'd0, get_a(edge_cnt-4'd1)};\n                        edge_damage[edge_cnt-4'd1] <= (k_temp - 32'd1) * {16'd0, get_a(edge_cnt-4'd1)};\n                    end\n                end\n\n                DIJK_INIT: begin\n                    // Initialize Dijkstra\n                    current_node <= 4'd0;\n                    dist[0] <= 32'd0;\n                    for (i = 1; i < 8; i = i + 1) begin\n                        dist[i] <= 32'hFFFFFFFF;\n                        visited[i] <= 1'b0;\n                    end\n                    node_cnt <= 4'd0;\n                    edge_cnt <= 4'd0;\n                    visited[0] <= 1'b0;\n                    state <= DIJK_SELECT;\n                end\n\n                DIJK_SELECT: begin\n                    if (node_cnt < n) begin\n                        if (!visited[node_cnt]) begin\n                            if ((dist[node_cnt] < dist[current_node]) || (current_node >= n)) begin\n                                current_node <= node_cnt;\n                            end\n                        end\n                        node_cnt <= node_cnt + 4'd1;\n                    end else begin\n                        if (dist[current_node] != 32'hFFFFFFFF) begin\n                            state <= DIJK_RELAX;\n                            visited[current_node] <= 1'b1;\n                            edge_cnt <= 4'd0;\n                        end else begin\n                            // No path found\n                            state <= OUTPUT;\n                        end\n                        node_cnt <= 4'd0;\n                    end\n                end\n\n                DIJK_RELAX: begin\n                    if (edge_cnt < m) begin\n                        if (edge_from[edge_cnt] == current_node) begin\n                            if (dist[edge_to[edge_cnt]] > (dist[current_node] + edge_damage[edge_cnt])) begin\n                                dist[edge_to[edge_cnt]] <= dist[current_node] + edge_damage[edge_cnt];\n                            end\n                        end\n                        edge_cnt <= edge_cnt + 4'd1;\n                    end else begin\n                        state <= DIJK_SELECT;\n                        node_cnt <= 4'd0;\n                        current_node <= 4'd0;  // Reset for next iteration\n                    end\n                end\n\n                OUTPUT: begin\n                    // Compute final result\n                    if (n == 4'd0) begin\n                        result <= 32'hFFFFFFFF;\n                    end else if (dist[n-4'd1] < H) begin\n                        result <= {16'd0, H} - dist[n-4'd1];\n                    end else begin\n                        result <= 32'hFFFFFFFF;  // Oh no\n                    end\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule